from __future__ import absolute_import

import time
import logging
from selenium.common.exceptions import TimeoutException
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages import v21a, v22r3
from taf.selenium.sbts_fsm3.pages.navigatable_page import NavigatablePage
from taf.selenium.sbts_fsm3.pages.panels.details import DetailPanel
from taf.selenium.sbts_fsm3.pages.panels.view import ViewPanel

from taf.selenium.core.html_table import HTMLTable


class Diagnostic(v22r3.Diagnostic):
    """
    The class corresponding to diagnostic page on sbts web, all operations under diagnostic
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver, download_checker):
        super(Diagnostic, self).__init__(driver, download_checker)
        self._troubleshooting_scripts = TroubleshootingScriptsPage(driver, download_checker)
        self._downlink = TestModelsNRDownlinkPage(driver)

    @property
    def troubleshooting_scripts(self):
        return self._troubleshooting_scripts


class TroubleshootingScriptsPage(NavigatablePage):
    _MENU_ROUTE_LIST = ['Diagnostic', 'Troubleshooting Scripts']

    def __init__(self, driver, download_checker):
        super(TroubleshootingScriptsPage, self).__init__(driver)
        self._view_panel = TroubleshootingScriptsViewPanel(driver, download_checker)

    def _get_route_list(self):
        return self._MENU_ROUTE_LIST

    def get_troubleshooting_scripts_details(self, script_owner_module='System module', script_name=None, timeout=60):
        return self._view_panel.get_troubleshooting_scripts_details(script_owner_module, script_name, timeout)

    def launch_troubleshooting_script(self, script_name, cells_name, bbmods_name, free_text,
                                      script_owner_module='System module', timeout=60):
        return self._view_panel.launch_troubleshooting_script(script_name, cells_name, bbmods_name, free_text,
                                                              script_owner_module, timeout)


class TroubleshootingScriptsViewPanel(ViewPanel):
    _SCRIPT_OWNER_MODULE_XPATH = '//*[@*="{}"]//span/..'
    _SCRIPT_OWNER_MODULE_CHECKED = '//p-radiobutton[@*="{}"]'
    _SCRIPT_XPATH = '//*[text()="Scripts"]//following::li//*'
    _SCRIPT_NAME = '//td[contains(text(), "Script name")]'
    _SCRIPT_TITLE = '//*[contains(@class, "troubleshooting-main-script")]/*[text()="{}"]'
    _CELLS_DROPDOWN_BUTTON = '//div[*[@title="Cell(s)"]]//p-multiselect/div'
    _BBMODS_DROPDOWN_BUTTON = '//div[*[@title="BBMOD(s)"]]//p-multiselect/div'
    _RMODS_DROPDOWN_BUTTON = '//div[*[@title="RMOD(s)"]]//p-multiselect/div'
    _LI_ITEM = '//p-multiselectitem//li'
    _FREE_TEXT_PARAMETERS = '//div[*[text()="Free text parameters"]]//textarea'
    _LAUNCH_SCRIPT = '//button[*[text()="Launch Script"]]'
    _LAUNCHING = '//div[contains(text(), "Launching..")]'
    _LAUNCHING_FAILED = '//div[contains(text(), "Launching failed")]'
    _LAUNCHING_PARTIALLY_SUCCEEDED = '//div[contains(text(), "Launching partially succeeded")]'
    _LAUNCHING_SUCCEEDED = '//div[contains(text(), "Launching succeeded")]'
    _COLLECTION_FILES = '//div[contains(text(), "Collecting files")]'
    _COLLECTION_COMPLETED = '//div[contains(text(), "Collection completed")]'
    _MODULE_MOD_MAPPING = {
        'System module': _BBMODS_DROPDOWN_BUTTON,
        'Radio module': _RMODS_DROPDOWN_BUTTON
    }

    def __init__(self, driver, download_checker):
        super(TroubleshootingScriptsViewPanel, self).__init__(driver, download_checker)
        self._detail_panel = TroubleshootingScriptsDetailPanel(driver)

    def get_troubleshooting_scripts_details(self, script_owner_module='System module', script_name=None, timeout=60):
        self.wait_for_text_present_in_attribute(self._SCRIPT_OWNER_MODULE_CHECKED.format(script_owner_module),
                                                'class',
                                                'valid')
        self.click_enabled_element((By.XPATH, self._SCRIPT_OWNER_MODULE_XPATH.format(script_owner_module)), timeout)

        try:
            self.wait_for_visibility_by_xpath(self._SCRIPT_XPATH)
        except TimeoutException:
            return {}
        self._detail_panel.expand_details_panel()
        info = {}
        for elem in self.driver.find_elements_by_xpath(self._SCRIPT_XPATH):
            elem.click()
            script_detail_table_info = self._detail_panel.get_scripts_detail_table_info()
            scripts_parameters_table_info = self._detail_panel.get_scripts_parameters_table_info()
            script_detail_table_info.update(scripts_parameters_table_info)
            info.update({elem.text: script_detail_table_info})

        if script_name:
            return info[script_name]
        return info

    def launch_troubleshooting_script(self, script_name, cells_name, mods_name, free_text=None,
                                      script_owner_module='System module', timeout=60):
        self.wait_for_text_present_in_attribute(self._SCRIPT_OWNER_MODULE_CHECKED.format(script_owner_module),
                                                'class',
                                                'valid')
        self.click_enabled_element((By.XPATH, self._SCRIPT_OWNER_MODULE_XPATH.format(script_owner_module)), timeout)
        self.wait_for_enable((By.XPATH, self._SCRIPT_XPATH), timeout)
        for elem in self.driver.find_elements_by_xpath(self._SCRIPT_XPATH):
            if elem.text == script_name:
                elem.click()
                self.wait_for_visibility_by_xpath(self._SCRIPT_TITLE.format(script_name))

        self._select_fixed_parameters(self._CELLS_DROPDOWN_BUTTON, cells_name, timeout)
        self._select_fixed_parameters(self._MODULE_MOD_MAPPING[script_owner_module], mods_name, timeout)
        self.insert_text_to_enable_element((By.XPATH, self._FREE_TEXT_PARAMETERS), free_text, timeout)

        self.click_enabled_element((By.XPATH, self._LAUNCH_SCRIPT), timeout)

        return self._launch_troubleshooting_script(timeout)

    def _launch_troubleshooting_script(self, timeout):
        launching_failed = False
        self.wait_for_visibility_by_xpath(self._LAUNCHING)
        self.wait_for_invisibility((By.XPATH, self._LAUNCHING), timeout)
        current_time = time.time()
        try:
            self.wait_for_visibility_by_xpath(self._LAUNCHING_FAILED, 8)
            launching_status = self.get_text_by_xpath(self._LAUNCHING_FAILED)
            launching_failed = True
        except TimeoutException:
            pass

        if not launching_failed:
            try:
                self.wait_for_visibility_by_xpath(self._LAUNCHING_PARTIALLY_SUCCEEDED, 8)
                launching_status = self.get_text_by_xpath(self._LAUNCHING_PARTIALLY_SUCCEEDED)
            except TimeoutException:
                self.wait_for_visibility_by_xpath(self._LAUNCHING_SUCCEEDED, 8)
                launching_status = self.get_text_by_xpath(self._LAUNCHING_SUCCEEDED)
            logging.info(launching_status)

        try:
            self.wait_for_visibility_by_xpath(self._COLLECTION_COMPLETED, timeout)
            collection_status = self.get_text_by_xpath(self._COLLECTION_COMPLETED, timeout)
            file_path = self.download_files(current_time)
        except TimeoutException:
            logging.info('can not wait collection completed')
            file_path = ''
            collection_status = ''

        status = {
            'Launching status': launching_status,
            'Collection status': collection_status,
            'Collection file': file_path
        }
        elem = self.wait_for_enable((By.XPATH, self._FREE_TEXT_PARAMETERS))
        self._clear_text_of_field(elem)
        return status

    def _select_fixed_parameters(self, dropdown_button, options, timeout=60):
        self.click_and_wait_for_corresponding_element_visible(dropdown_button, self._LI_ITEM)
        for elem in self.driver.find_elements_by_xpath(self._LI_ITEM):
            class_attr = elem.get_attribute('class')
            label = elem.get_attribute('aria-label')
            if 'highlight' in class_attr and label not in options:
                elem.click()
            if 'highlight' not in class_attr and label in options:
                elem.click()
        self.click_enabled_element((By.XPATH, dropdown_button), timeout)


class TroubleshootingScriptsDetailPanel(DetailPanel):
    _FREE_TEXT_PARAMETERS = 'Free text parameters'
    _SCRIPTS_DETAILS_TABLE = '//scripts-details//*[contains(@class, "details-table")]//table'
    _SCRIPTS_PARAMETERS_TABLE = '//scripts-details//*[contains(@class, "script-parameters-table")]//table'

    def __init__(self, driver):
        super(TroubleshootingScriptsDetailPanel, self).__init__(driver)

    def get_scripts_detail_table_info(self):
        table = HTMLTable(self.driver, self._SCRIPTS_DETAILS_TABLE)
        info = table.get_table()
        keys = [value.strip(':') for value in list(info.values())[0]]
        values = list(info.values())[1]
        return dict(zip(keys, values))

    def get_scripts_parameters_table_info(self):
        th_elems = self.driver.find_elements_by_xpath(self._SCRIPTS_PARAMETERS_TABLE + '//thead//th')
        columns_title = [elem.text.strip() for elem in th_elems]

        tr_values = []
        tr_elems = self.driver.find_elements_by_xpath(self._SCRIPTS_PARAMETERS_TABLE + '//tbody//tr')
        if 1 == len(tr_elems):
            tr_elems = tr_elems * len(columns_title)

        for tr_elem in tr_elems:
            values = []
            for tr_elem in tr_elem.find_elements_by_xpath('.//td'):
                colspan = tr_elem.get_attribute('colspan')
                if colspan is not None and len(columns_title) == int(colspan):
                    values = [tr_elem.text.strip() for _ in range(len(columns_title))]
                else:
                    values.append(tr_elem.text.strip())
            tr_values.append(dict(zip(columns_title, values)))
        return {self._FREE_TEXT_PARAMETERS: tr_values}


class TestModelsNRDownlinkPage(v21a.diagnostic.TestModelsNRDownlinkPage):
    def __init__(self, driver):
        super(TestModelsNRDownlinkPage, self).__init__(driver)
        self._view_panel = TestModelsNRDownlinkPageViewPanel(driver)

    def start_test(self, *args, **kwargs):
        self._view_panel.start_test(*args, **kwargs)


class TestModelsNRDownlinkPageViewPanel(v21a.diagnostic.TestModelsNRDownlinkPageViewPanel):
    _TYPE_OF_LOAD_LIST_BUTTON_XPATH = '//div[contains(text(), "Type of load")]/parent::*//button'
    _TYPE_OF_LOAD_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Type of load")]/parent::*//ul//li'
    _LEVEL_OF_LOAD_FLAT_LIST_BUTTON_XPATH = '//div[contains(text(), "Level of load flat")]/parent::*//button'
    _LEVEL_OF_LOAD_FLAT_DROPDOWN_LIST_OPTIONS_XPATH = '//div[contains(text(), "Level of load flat")]/parent::*//ul//li'
    _LEVEL_OF_LOAD_BURST_LIST_BUTTON_XPATH = '//div[contains(text(), "Level of load burst")]/parent::*//button'
    _LEVEL_OF_LOAD_BURST_DROPDOWN_LIST_OPTIONS_XPATH = ('//div[contains(text(), "Level of load burst")]'
                                                        '/parent::*//ul//li')
    _SPEC_SSB_BEAM_PATTERN_ID = '//div[contains(text(), "Specifies SSB beam pattern ID")]/parent::*//input'

    def __init__(self, driver):
        super(TestModelsNRDownlinkPageViewPanel, self).__init__(driver)

    def _configure_downlink_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                                 beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None,
                                 type_of_load=None, level_of_load_flat=None, level_of_load_burst=None,
                                 spec_ssb_beam_pattern=None):
        super(TestModelsNRDownlinkPageViewPanel, self)._configure_downlink_test(local_cell=local_cell,
                                                                                test_model=test_model,
                                                                                p_max=p_max,
                                                                                timeout=timeout,
                                                                                polarization=polarization,
                                                                                physical_cell_id=physical_cell_id,
                                                                                beam_id=beam_id,
                                                                                nrarfcn_downlink=nrarfcn_downlink,
                                                                                nrarfcn_uplink=nrarfcn_uplink,
                                                                                nrarfcn=nrarfcn)
        if type_of_load is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                type_of_load,
                (By.XPATH, self._TYPE_OF_LOAD_LIST_BUTTON_XPATH),
                (By.XPATH, self._TYPE_OF_LOAD_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        if level_of_load_flat is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                level_of_load_flat,
                (By.XPATH, self._LEVEL_OF_LOAD_FLAT_LIST_BUTTON_XPATH),
                (By.XPATH, self._LEVEL_OF_LOAD_FLAT_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        if level_of_load_burst is not None:
            self.select_element_from_dropdown_list_by_text_and_click(
                level_of_load_burst,
                (By.XPATH, self._LEVEL_OF_LOAD_BURST_LIST_BUTTON_XPATH),
                (By.XPATH, self._LEVEL_OF_LOAD_BURST_DROPDOWN_LIST_OPTIONS_XPATH),
                timeout
            )

        if spec_ssb_beam_pattern is not None:
            self.insert_text_to_enable_element((By.XPATH, self._SPEC_SSB_BEAM_PATTERN_ID),
                                               spec_ssb_beam_pattern,
                                               timeout)

    def start_test(self, local_cell, test_model, p_max, timeout, polarization, physical_cell_id=None,
                   beam_id=None, nrarfcn_downlink=None, nrarfcn_uplink=None, nrarfcn=None, type_of_load=None,
                   level_of_load_flat=None, level_of_load_burst=None, spec_ssb_beam_pattern=None):
        timeout = int(timeout)
        self._configure_downlink_test(local_cell=local_cell,
                                      test_model=test_model,
                                      p_max=p_max,
                                      timeout=timeout,
                                      polarization=polarization,
                                      physical_cell_id=physical_cell_id,
                                      beam_id=beam_id,
                                      nrarfcn_downlink=nrarfcn_downlink,
                                      nrarfcn_uplink=nrarfcn_uplink,
                                      nrarfcn=nrarfcn,
                                      type_of_load=type_of_load,
                                      level_of_load_flat=level_of_load_flat,
                                      level_of_load_burst=level_of_load_burst,
                                      spec_ssb_beam_pattern=spec_ssb_beam_pattern)
        self.click_enabled_element((By.XPATH, self._START_TEST_BUTTON_XPATH), timeout)
